package com.payflow;
import com.payflow.auth.*;import com.payflow.common.ApiException;import com.payflow.ledger.*;import com.payflow.reconciliation.*;import com.payflow.transaction.*;import com.payflow.user.*;import com.payflow.wallet.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.test.context.DynamicPropertySource;
import java.util.*;import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
@EnabledIfSystemProperty(named="run.pg",matches="true") @SpringBootTest(properties={"payflow.jwt-secret=test-secret-that-is-long-enough-for-hmac-signing","spring.task.scheduling.enabled=false"})
class PayFlowPostgresTest {
  @DynamicPropertySource static void db(DynamicPropertyRegistry r){r.add("spring.datasource.url",()->"jdbc:postgresql://localhost:55432/payflow_test");r.add("spring.datasource.username",()->System.getProperty("user.name"));r.add("spring.datasource.password",()->"");}
  @Autowired AuthService auth;@Autowired UserRepository users;@Autowired WalletRepository wallets;@Autowired TransactionEngine engine;@Autowired TransactionRepository txs;@Autowired LedgerRepository ledger;@Autowired ReconciliationService reconciliation;@Autowired JdbcTemplate jdbc;
  User user(String prefix){String id=UUID.randomUUID().toString();long n=Math.abs(UUID.randomUUID().getMostSignificantBits()%1_000_000_000L);String email=prefix.toLowerCase()+"-"+id+"@test.local",phone="9"+String.format("%09d",n);auth.register(new AuthController.RegisterRequest(prefix,email,phone,"Password1!"));return users.findByEmail(email).orElseThrow();}
  @Test void registrationCreatesExactlyOneZeroWallet(){User u=user("Register");Wallet w=wallets.findByOwnerId(u.getId()).orElseThrow();assertEquals(0,w.getBalancePaise());assertEquals(Wallet.AccountType.PERSONAL,w.getAccountType());}
  @Test void normalTransferProducesTwoPostings(){User a=user("NormalA"),b=user("NormalB");engine.topup(a,100_000,"normal-fund-"+a.getId());var result=engine.transfer(a,wallets.findByOwnerId(b.getId()).orElseThrow().getId(),30_000,"normal","normal-transfer-"+a.getId());assertEquals(70_000,wallets.findByOwnerId(a.getId()).orElseThrow().getBalancePaise());assertEquals(30_000,wallets.findByOwnerId(b.getId()).orElseThrow().getBalancePaise());assertEquals(2,ledger.countByTransactionId(txs.findByReference(result.reference()).orElseThrow().getId()));}
  @Test void concurrentIncomingTransfersHaveNoLostUpdate()throws Exception{User receiver=user("Receiver"),b=user("CreditB"),c=user("CreditC");engine.topup(receiver,100_000,"receiver-fund-"+receiver.getId());engine.topup(b,50_000,"b-fund-"+b.getId());engine.topup(c,30_000,"c-fund-"+c.getId());Long target=wallets.findByOwnerId(receiver.getId()).orElseThrow().getId();var pool=Executors.newFixedThreadPool(2);var gate=new CyclicBarrier(2);Future<?> f1=pool.submit(()->run(gate,()->engine.transfer(b,target,50_000,null,"credit-b-"+b.getId())));Future<?> f2=pool.submit(()->run(gate,()->engine.transfer(c,target,30_000,null,"credit-c-"+c.getId())));f1.get(10,TimeUnit.SECONDS);f2.get(10,TimeUnit.SECONDS);assertEquals(180_000,wallets.findByOwnerId(receiver.getId()).orElseThrow().getBalancePaise());pool.shutdown();}
  @Test void doubleSpendAllowsOneAndNeverOverdraws()throws Exception{User a=user("Double"),b=user("DoubleB"),c=user("DoubleC");engine.topup(a,100_000,"double-fund-"+a.getId());var pool=Executors.newFixedThreadPool(2);var gate=new CyclicBarrier(2);List<Future<Boolean>> fs=new ArrayList<>();for(User dest:List.of(b,c))fs.add(pool.submit(()->{gate.await();try{engine.transfer(a,wallets.findByOwnerId(dest.getId()).orElseThrow().getId(),80_000,null,"double-"+dest.getId());return true;}catch(ApiException e){assertEquals("INSUFFICIENT_BALANCE",e.code());return false;}}));int successes=0;for(var f:fs)if(f.get(10,TimeUnit.SECONDS))successes++;assertEquals(1,successes);assertEquals(20_000,wallets.findByOwnerId(a.getId()).orElseThrow().getBalancePaise());pool.shutdown();}
  @Test void fiftyDuplicateRequestsCommitOneMovement()throws Exception{User a=user("IdemA"),b=user("IdemB");engine.topup(a,100_000,"idem-fund-"+a.getId());Long target=wallets.findByOwnerId(b.getId()).orElseThrow().getId();long txBefore=txs.count(),ledgerBefore=ledger.count();var pool=Executors.newFixedThreadPool(12);var gate=new CountDownLatch(1);List<Future<UUID>> fs=new ArrayList<>();for(int i=0;i<50;i++)fs.add(pool.submit(()->{gate.await();return engine.transfer(a,target,20_000,"same","identical-"+a.getId()).reference();}));gate.countDown();Set<UUID> refs=new HashSet<>();for(var f:fs)refs.add(f.get(20,TimeUnit.SECONDS));assertEquals(1,refs.size());assertEquals(txBefore+1,txs.count());assertEquals(ledgerBefore+2,ledger.count());assertEquals(80_000,wallets.findByOwnerId(a.getId()).orElseThrow().getBalancePaise());pool.shutdown();}
  @Test void idempotencyConflictAndReconciliation(){User a=user("ConflictA"),b=user("ConflictB");engine.topup(a,50_000,"conflict-fund-"+a.getId());Long target=wallets.findByOwnerId(b.getId()).orElseThrow().getId();String key="conflict-transfer-"+a.getId();engine.transfer(a,target,10_000,null,key);ApiException error=assertThrows(ApiException.class,()->engine.transfer(a,target,20_000,null,key));assertEquals("IDEMPOTENCY_CONFLICT",error.code());var report=reconciliation.run();assertTrue(report.passed(),report.discrepancies().toString());}
  @Test void fiftyConcurrentIncomingTransfersCommitWithoutLostUpdates()throws Exception{User receiver=user("StressReceiver");engine.topup(receiver,100_000,"stress-receiver-fund-"+receiver.getId());Long target=wallets.findIdByOwnerId(receiver.getId()).orElseThrow();List<User> senders=new ArrayList<>();for(int i=0;i<50;i++){User sender=user("StressSender"+i);engine.topup(sender,10_000,"stress-fund-"+sender.getId());senders.add(sender);}long txBefore=txs.count(),ledgerBefore=ledger.count();var pool=Executors.newFixedThreadPool(12);var start=new CountDownLatch(1);List<Future<?>> futures=new ArrayList<>();for(User sender:senders)futures.add(pool.submit(()->{start.await();engine.transfer(sender,target,10_000,null,"stress-in-"+sender.getId());return null;}));start.countDown();for(var f:futures)f.get(30,TimeUnit.SECONDS);pool.shutdown();assertEquals(600_000,wallets.findByOwnerId(receiver.getId()).orElseThrow().getBalancePaise());assertEquals(50,txs.count()-txBefore);assertEquals(100,ledger.count()-ledgerBefore);assertTrue(reconciliation.run().passed());}
  @Test void fiftyConcurrentDebitsCommitTenAndRejectForty()throws Exception{User sender=user("DebitStress");engine.topup(sender,100_000,"debit-stress-fund-"+sender.getId());List<Long> targets=new ArrayList<>();for(int i=0;i<50;i++)targets.add(wallets.findIdByOwnerId(user("DebitTarget"+i).getId()).orElseThrow());long txBefore=txs.count(),ledgerBefore=ledger.count();var ok=new java.util.concurrent.atomic.AtomicInteger();var rejected=new java.util.concurrent.atomic.AtomicInteger();var unexpected=new java.util.concurrent.atomic.AtomicInteger();var pool=Executors.newFixedThreadPool(12);var start=new CountDownLatch(1);List<Future<?>> futures=new ArrayList<>();for(Long target:targets)futures.add(pool.submit(()->{start.await();try{engine.transfer(sender,target,10_000,null,"stress-out-"+target);ok.incrementAndGet();}catch(ApiException e){if("INSUFFICIENT_BALANCE".equals(e.code()))rejected.incrementAndGet();else unexpected.incrementAndGet();}return null;}));start.countDown();for(var f:futures)f.get(30,TimeUnit.SECONDS);pool.shutdown();assertEquals(10,ok.get());assertEquals(40,rejected.get());assertEquals(0,unexpected.get());assertEquals(0,wallets.findByOwnerId(sender.getId()).orElseThrow().getBalancePaise());assertEquals(10,txs.count()-txBefore);assertEquals(20,ledger.count()-ledgerBefore);assertTrue(reconciliation.run().passed());}
  @Test void retryAfterCommitReturnsOriginalMovement(){User sender=user("RetrySender"),receiver=user("RetryReceiver");engine.topup(sender,100_000,"retry-fund-"+sender.getId());Long target=wallets.findIdByOwnerId(receiver.getId()).orElseThrow();long before=txs.count();String key="retry-transfer-"+sender.getId();var first=engine.transfer(sender,target,20_000,"retry",key);var replay=engine.transfer(sender,target,20_000,"retry",key);assertEquals(first.reference(),replay.reference());assertEquals(before+1,txs.count());assertEquals(80_000,wallets.findByOwnerId(sender.getId()).orElseThrow().getBalancePaise());assertEquals(20_000,wallets.findByOwnerId(receiver.getId()).orElseThrow().getBalancePaise());}
  @Test void injectedFailureRollsBackFlushedDebit(){User sender=user("RollbackSender"),receiver=user("RollbackReceiver");engine.topup(sender,100_000,"rollback-fund-"+sender.getId());Long target=wallets.findIdByOwnerId(receiver.getId()).orElseThrow();long txBefore=txs.count(),ledgerBefore=ledger.count();assertThrows(IllegalStateException.class,()->engine.transferWithInjectedFailure(sender,target,30_000));assertEquals(100_000,wallets.findByOwnerId(sender.getId()).orElseThrow().getBalancePaise());assertEquals(0,wallets.findByOwnerId(receiver.getId()).orElseThrow().getBalancePaise());assertEquals(txBefore,txs.count());assertEquals(ledgerBefore,ledger.count());}
  @Test void oppositeDirectionTransfersCompleteWithOrderedLocks()throws Exception{User a=user("OppositeA"),b=user("OppositeB");engine.topup(a,100_000,"opposite-fund-a-"+a.getId());engine.topup(b,100_000,"opposite-fund-b-"+b.getId());var pool=Executors.newFixedThreadPool(2);var gate=new CyclicBarrier(2);Future<?> one=pool.submit(()->run(gate,()->engine.transfer(a,wallets.findIdByOwnerId(b.getId()).orElseThrow(),20_000,null,"opposite-a-"+a.getId())));Future<?> two=pool.submit(()->run(gate,()->engine.transfer(b,wallets.findIdByOwnerId(a.getId()).orElseThrow(),30_000,null,"opposite-b-"+b.getId())));one.get(10,TimeUnit.SECONDS);two.get(10,TimeUnit.SECONDS);pool.shutdown();assertEquals(110_000,wallets.findByOwnerId(a.getId()).orElseThrow().getBalancePaise());assertEquals(90_000,wallets.findByOwnerId(b.getId()).orElseThrow().getBalancePaise());assertTrue(reconciliation.run().passed());}
  @Test void concurrentDuplicateRegistrationCreatesOneUserAndWallet()throws Exception{String id=UUID.randomUUID().toString(),email="same-"+id+"@test.local",phone="8"+String.format("%09d",Math.abs(UUID.randomUUID().getMostSignificantBits()%1_000_000_000L));var request=new AuthController.RegisterRequest("Same Person",email,phone,"Password1!");var pool=Executors.newFixedThreadPool(2);var gate=new CyclicBarrier(2);List<Future<Boolean>> futures=new ArrayList<>();for(int i=0;i<2;i++)futures.add(pool.submit(()->{gate.await();try{auth.register(request);return true;}catch(ApiException e){assertEquals("DUPLICATE_ACCOUNT",e.code());return false;}}));int successes=0;for(var f:futures)if(f.get(10,TimeUnit.SECONDS))successes++;pool.shutdown();assertEquals(1,successes);User created=users.findByEmail(email).orElseThrow();assertTrue(wallets.findByOwnerId(created.getId()).isPresent());}
  @Test void reconciliationDetectsIsolatedStoredBalanceMismatch(){User u=user("ReconcileDetection");engine.topup(u,10_000,"reconcile-detection-"+u.getId());Long walletId=wallets.findIdByOwnerId(u.getId()).orElseThrow();try{jdbc.update("update wallets set balance_paise=balance_paise+1 where id=?",walletId);assertFalse(reconciliation.run().passed());}finally{jdbc.update("update wallets set balance_paise=balance_paise-1 where id=?",walletId);}assertTrue(reconciliation.run().passed());}
  @Test void concurrentTopupsAreAllAccountedFor()throws Exception{User owner=user("TopupStress");long txBefore=txs.count(),ledgerBefore=ledger.count();var pool=Executors.newFixedThreadPool(10);var start=new CountDownLatch(1);List<Future<?>> futures=new ArrayList<>();for(int i=0;i<20;i++){int request=i;futures.add(pool.submit(()->{start.await();engine.topup(owner,10_000,"concurrent-topup-"+owner.getId()+"-"+request);return null;}));}start.countDown();for(var f:futures)f.get(20,TimeUnit.SECONDS);pool.shutdown();assertEquals(200_000,wallets.findByOwnerId(owner.getId()).orElseThrow().getBalancePaise());assertEquals(20,txs.count()-txBefore);assertEquals(40,ledger.count()-ledgerBefore);assertTrue(reconciliation.run().passed());}
  static void run(CyclicBarrier b,Runnable action){try{b.await();action.run();}catch(Exception e){throw new RuntimeException(e);}}
}
